// N5 content generated by scripts/ingest/build-n5.ts (validated there and in scripts/validate-content.ts).
import grammarJson from '../../../content/levels/n5/grammar.json';
import kanjiJson from '../../../content/levels/n5/kanji.json';
import lessonsJson from '../../../content/levels/n5/lessons.json';
import wordsJson from '../../../content/levels/n5/words.json';
import type { GrammarPoint, Kanji, Lesson, Word } from './schemas';

export const words = wordsJson as Word[];
export const kanjiList = kanjiJson as Kanji[];
export const grammarPoints = grammarJson as GrammarPoint[];
export const lessons = (lessonsJson as Lesson[]).toSorted((a, b) => a.order - b.order);

const wordById = new Map(words.map((w) => [w.id, w]));
const kanjiByChar = new Map(kanjiList.map((k) => [k.char, k]));
const grammarById = new Map(grammarPoints.map((g) => [g.id, g]));

export const getWord = (id: string) => wordById.get(id);
export const getKanji = (char: string) => kanjiByChar.get(char);
export const getGrammar = (id: string) => grammarById.get(id);
export const getLesson = (id: string) => lessons.find((l) => l.id === id);

/** Lesson slug in URLs is its order ("1".."30"). */
export const lessonByOrder = (order: number) => lessons.find((l) => l.order === order);

export function lessonContent(lesson: Lesson) {
  return {
    words: lesson.wordIds.map((id) => wordById.get(id)!).filter(Boolean),
    kanji: lesson.kanji.map((c) => kanjiByChar.get(c)!).filter(Boolean),
    grammar: lesson.grammarIds.map((id) => grammarById.get(id)!).filter(Boolean),
  };
}

/** Words that use a kanji, for the kanji detail page. */
export const wordsWithKanji = (char: string) => words.filter((w) => w.surface.includes(char));
